// ReplaySnapshot resolver
func (r *queryResolver) ReplaySnapshot(ctx context.Context, sessionDate string, time *string) (*model.ReplaySnapshot, error) {
	asOf := "15:30:00"
	if time != nil && *time != "" {
		asOf = *time
	}

	// Use precise timestamp range for index scan on (instrument_id, ts DESC)
	// Database timestamps are stored in UTC, sessionDate and asOf are IST (+05:30)
	startTs := fmt.Sprintf("%s 09:15:00+05:30", sessionDate)
	endTs := fmt.Sprintf("%s %s+05:30", sessionDate, asOf)

	sql := `
		WITH latest_min AS (
			SELECT DISTINCT ON (f.instrument_id)
				i.symbol,
				COALESCE(i.sector, 'OTHERS') as sector,
				f.cash_close as price,
				ROUND(((f.cash_close - df.prior_close) / NULLIF(df.prior_close, 0) * 100)::numeric, 2) as move_pct,
				ROUND(((f.session_open - df.prior_close) / NULLIF(df.prior_close, 0) * 100)::numeric, 2) as gap_pct,
				ROUND(COALESCE(f.session_vwap, f.cash_close)::numeric, 2) as vwap,
				ROUND(((f.cash_close - COALESCE(f.session_vwap, f.cash_close)) / NULLIF(COALESCE(f.session_vwap, f.cash_close), 0) * 100)::numeric, 2) as vwap_dist_pct,
				ROUND(COALESCE(f.relative_volume, 1.0)::numeric, 2) as rvol,
				ROUND(COALESCE(f.clv, 0)::numeric, 2) as clv,
				f.cumulative_volume as volume,
				(f.cash_close >= COALESCE(f.session_vwap, f.cash_close)) as is_above_vwap
			FROM market.intraday_features_1m f
			JOIN market.instruments i ON f.instrument_id = i.id
			JOIN market.daily_features df ON df.instrument_id = i.id AND df.feature_run_id = f.feature_run_id
			WHERE f.ts >= $1::timestamptz AND f.ts <= $2::timestamptz
			ORDER BY f.instrument_id, f.ts DESC
		)
		SELECT 
			symbol,
			sector,
			price,
			move_pct,
			gap_pct,
			vwap,
			vwap_dist_pct,
			rvol,
			clv,
			volume,
			is_above_vwap
		FROM latest_min
		ORDER BY rvol DESC;
	`

	rows, err := r.DB.Pool.Query(ctx, sql, startTs, endTs)
	if err != nil {
		return nil, fmt.Errorf("query replay snapshot: %w", err)
	}
	defer rows.Close()

	stocks := []*model.ReplayStock{}
	aboveVwap := 0
	belowVwap := 0

	sectorStats := make(map[string]*struct {
		count      int
		sumMove    float64
		sumRvol    float64
		aboveCount int
	})

	for rows.Next() {
		var s model.ReplayStock
		var price, movePct, gapPct, vwap, vwapDist, rvol, clv float64
		var vol int64
		var isAbove bool
		var sym, sec string

		if err := rows.Scan(
			&sym,
			&sec,
			&price,
			&movePct,
			&gapPct,
			&vwap,
			&vwapDist,
			&rvol,
			&clv,
			&vol,
			&isAbove,
		); err != nil {
			return nil, fmt.Errorf("scan replay stock: %w", err)
		}

		resolvedSector := sec
		if resolvedSector == "" || resolvedSector == "N/A" || resolvedSector == "OTHERS" {
			fallback := sector.Resolve(sym)
			if fallback != "" && fallback != "OTHERS" {
				resolvedSector = fallback
			}
		}

		s.Symbol = sym
		s.Sector = resolvedSector
		s.Price = price
		s.MovePct = movePct
		s.GapPct = gapPct
		s.Vwap = vwap
		s.VwapDistPct = vwapDist
		s.Rvol = rvol
		s.Clv = clv
		s.Volume = float64(vol)
		s.IsAboveVwap = isAbove

		if isAbove {
			aboveVwap++
		} else {
			belowVwap++
		}
		stocks = append(stocks, &s)

		st := sectorStats[resolvedSector]
		if st == nil {
			st = &struct {
				count      int
				sumMove    float64
				sumRvol    float64
				aboveCount int
			}{}
			sectorStats[resolvedSector] = st
		}
		st.count++
		st.sumMove += movePct
		st.sumRvol += rvol
		if isAbove {
			st.aboveCount++
		}
	}

	total := len(stocks)
	pctAbove := 0.0
	if total > 0 {
		pctAbove = float64(aboveVwap) / float64(total) * 100
	}

	sectorsList := []*model.ReplaySector{}
	for secName, st := range sectorStats {
		if st.count == 0 {
			continue
		}
		avgMove := st.sumMove / float64(st.count)
		avgRvol := st.sumRvol / float64(st.count)
		pctAbv := float64(st.aboveCount) / float64(st.count) * 100
		sectorsList = append(sectorsList, &model.ReplaySector{
			Sector:       secName,
			CivCount:     st.count,
			AvgMovePct:   avgMove,
			AvgRvol:      avgRvol,
			PctAboveVwap: pctAbv,
		})
	}

	return &model.ReplaySnapshot{
		SessionDate: sessionDate,
		AsOfTime:    asOf,
		Weather: &model.ReplayWeather{
			TotalCivs:    total,
			AboveVwap:    aboveVwap,
			BelowVwap:    belowVwap,
			PctAboveVwap: pctAbove,
		},
		Stocks:  stocks,
		Sectors: sectorsList,
		Traps:   []*model.ReplayTrap{},
	}, nil
}

// ReplayCandles resolver
func (r *queryResolver) ReplayCandles(ctx context.Context, sessionDate string, symbol string, toTime *string, interval *string) ([]*model.Candle, error) {
	asOf := "15:30:00"
	if toTime != nil && *toTime != "" {
		asOf = *toTime
	}

	sql := `
		SELECT 
			EXTRACT(EPOCH FROM c.ts)::int as time,
			c.open,
			c.high,
			c.low,
			c.close,
			c.volume,
			COALESCE(f.session_vwap, c.close) as vwap,
			f.vwap_upper_1,
			f.vwap_lower_1,
			f.vwap_upper_2,
			f.vwap_lower_2,
			COALESCE(f.relative_volume, 1.0) as rvol
		FROM market.cash_candles_1m c
		JOIN market.instruments i ON c.instrument_id = i.id
		LEFT JOIN market.intraday_features_1m f ON f.instrument_id = i.id AND f.ts = c.ts
		WHERE i.symbol = $1 
		  AND (c.ts AT TIME ZONE 'Asia/Kolkata')::date = $2::date 
		  AND (c.ts AT TIME ZONE 'Asia/Kolkata')::time >= '09:15:00'::time
		  AND (c.ts AT TIME ZONE 'Asia/Kolkata')::time <= $3::time
		ORDER BY c.ts ASC;
	`

	rows, err := r.DB.Pool.Query(ctx, sql, symbol, sessionDate, asOf)
	if err != nil {
		return nil, fmt.Errorf("query replay candles: %w", err)
	}
	defer rows.Close()

	candles := []*model.Candle{}
	for rows.Next() {
		var c model.Candle
		var t int64
		var open, high, low, close, vwap, rvol float64
		var vol int64
		var u1, l1, u2, l2 *float64

		if err := rows.Scan(
			&t,
			&open,
			&high,
			&low,
			&close,
			&vol,
			&vwap,
			&u1,
			&l1,
			&u2,
			&l2,
			&rvol,
		); err != nil {
			return nil, err
		}

		c.Time = int(t)
		c.Open = open
		c.High = high
		c.Low = low
		c.Close = close
		c.Volume = float64(vol)
		c.Vwap = vwap
		c.VwapUpper1 = u1
		c.VwapLower1 = l1
		c.VwapUpper2 = u2
		c.VwapLower2 = l2
		c.Rvol = &rvol

		candles = append(candles, &c)
	}
	return candles, nil
}

